public class ProgressBarPrinterTest {
    static int failures = 0;

    static void check(String label, Object expected, Object actual) {
        if (java.util.Objects.equals(expected, actual)) {
            System.out.println("PASS  " + label);
        } else {
            System.out.println("FAIL  " + label + " -- expected " + quote(expected) + " but got " + quote(actual));
            failures++;
        }
    }

    static String quote(Object value) {
        if (value == null) {
            return "null";
        }
        return "\"" + value.toString().replace("\n", "\\n") + "\"";
    }

    static String capture(int percent, int width) {
        java.io.ByteArrayOutputStream buf = new java.io.ByteArrayOutputStream();
        java.io.PrintStream old = System.out;
        System.setOut(new java.io.PrintStream(buf));
        try {
            ProgressBarPrinter.printBar(percent, width);
        } catch (RuntimeException ex) {
            System.setOut(old);
            return "threw " + ex;
        } finally {
            System.setOut(old);
        }
        return buf.toString().replace(System.lineSeparator(), "\n");
    }

    public static void main(String[] args) {
        check("printBar(40, 10)", "[####------] 40%\n", capture(40, 10));
        check("printBar(100, 10)", "[##########] 100%\n", capture(100, 10));
        check("printBar(0, 5)", "[-----] 0%\n", capture(0, 5));
        check("printBar(33, 6) -- integer division", "[#-----] 33%\n", capture(33, 6));
        check("printBar(99, 10) -- not full yet", "[#########-] 99%\n", capture(99, 10));
        check("printBar(150, 4) -- clamped high", "[####] 100%\n", capture(150, 4));
        check("printBar(-20, 4) -- clamped low", "[----] 0%\n", capture(-20, 4));
        check("printBar(50, 1)", "[-] 50%\n", capture(50, 1));
        if (failures > 0) {
            System.out.println(failures + " test(s) failed.");
            System.exit(1);
        }
        System.out.println("ALL TESTS PASSED");
    }
}

