public class ProgressBarPrinter {

    public static void printBar(int percent, int width) {
        if (percent < 0) {
            percent = 0;
        }
        if (percent > 100) {
            percent = 100;
        }
        int filled = percent * width / 100;
        System.out.print("[");
        for (int i = 0; i < width; i++) {
            if (i < filled) {
                System.out.print("#");
            } else {
                System.out.print("-");
            }
        }
        System.out.println("] " + percent + "%");
    }
}
